using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class FieldSupplyTests
{
    static WorldSession New()=>new(FieldSupply.Create());
    static void At(WorldSession s,long at){while(s.Seconds<at){s.SetPaused(false);long before=s.Seconds;s.AdvanceTo(at);Assert.True(s.Seconds>before);}}
    static CommandResult Load(WorldSession s,long n=10000,string id="request:pack",bool loading=true)=>s.HandleSupply(new(id),s.PlayerControl,loading,n,s.Revision);
    static void Deploy(WorldSession s){At(s,2);s.Open(s.PlayerControl,RegionalWork.Inbox(s).Single(c=>c.CanOpen).Message,s.Revision);At(s,9);Assert.Equal(ResultCode.Accepted,s.SetRegionalActive(true,s.Revision).Code);}
    static long Qty(WorldSession s,EntityId id)=>s.DiagnosticSnapshot().ResourceLots.Single(l=>l.Id==id).Quantity;
    [Fact] public void InitialSupplyBelongsToHouseAndCarryIsEmpty(){var w=FieldSupply.Create();Assert.Equal(0,FieldSupply.Carried(w).Quantity);Assert.Equal(FieldSupply.Initial,w.ResourceLots.Single(l=>l.Id==FieldSupply.Depot).Quantity);Assert.All(w.ResourceLots.Where(l=>l.Unit==FieldSupply.Unit),l=>Assert.Equal(RetainerStart.House,l.Owner));Assert.Equal(w.PlayerControl,FieldSupply.Carried(w).MobileHolder);}
    [Fact] public void AtomicLoadingAndReturnConserveBothLots(){var s=New();Assert.Equal(ResultCode.Accepted,Load(s).Code);Assert.Equal(10000,Qty(s,FieldSupply.Carry));Assert.Equal(FieldSupply.Initial-10000,Qty(s,FieldSupply.Depot));Assert.Equal(ResultCode.Accepted,Load(s,4000,"request:unpack",false).Code);Assert.Equal(FieldSupply.Initial,Qty(s,FieldSupply.Depot)+Qty(s,FieldSupply.Carry));}
    [Fact] public void DuplicateIdAndConflictingQuantityNeverAllocateTwice(){var s=New();Load(s);var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.AlreadyAccepted,Load(s).Code);Assert.Equal(ResultCode.IdPayloadConflict,Load(s,999).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Theory][InlineData(-1)][InlineData(0)][InlineData(17280001)][InlineData(long.MaxValue)]
    public void InvalidOrExcessiveLoadCannotMutate(long n){var s=New();string hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Load(s,n).Code);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
    [Fact] public void EmptyCarryCannotDeploy(){var s=New();At(s,2);s.Open(s.PlayerControl,RegionalWork.Inbox(s).Single(c=>c.CanOpen).Message,s.Revision);At(s,9);Assert.Equal(ResultCode.NotAvailable,s.SetRegionalActive(true,s.Revision).Code);}
    [Fact] public void PhysicalCustodianMovesAndRemoteRefillIsRejected(){var s=New();Load(s);Deploy(s);var w=s.DiagnosticSnapshot();Assert.Equal(w.Locations.Single(l=>l.Actor==s.PlayerControl),FieldSupply.Location(w,FieldSupply.Carried(w)));Assert.Equal(LocationKind.AtPosition,FieldSupply.Location(w,FieldSupply.Carried(w)).Kind);Assert.Equal(ResultCode.NotAvailable,Load(s,1,"request:remote").Code);Assert.Equal(ResultCode.NotAvailable,Load(s,1,"request:remote-back",false).Code);}
    [Fact] public void RealSecondsConsumePersonSecondsAndCoalesce(){var s=New();Load(s);Deploy(s);At(s,39);Assert.Equal(7000,Qty(s,FieldSupply.Carry));Assert.Single(s.DiagnosticSnapshot().Supply!.Uses);Assert.Equal(new SupplyUse(9,39,100,3000),s.DiagnosticSnapshot().Supply!.Uses.Single());}
    [Fact] public void ShortageDoesNotDestroyOrKillAnyone(){var s=New();Load(s,150);Deploy(s);At(s,20);Assert.Equal(0,Qty(s,FieldSupply.Carry));var w=s.DiagnosticSnapshot();Assert.All(w.Region!.Units.Where(u=>u.Commander==s.PlayerControl),u=>Assert.Equal(u.InitialSoldiers,u.Soldiers));Assert.Equal(LifeState.Adult,w.Characters.Single(c=>c.Id==s.PlayerControl).Life);Assert.True(w.Supply!.Uses.Length<=3);Assert.Equal(150,w.Supply.Uses.Sum(u=>u.Consumed));}
    [Fact] public void PeaceAndPausedTimeDoNotConsume(){var s=New();Load(s);At(s,2);Assert.Equal(10000,Qty(s,FieldSupply.Carry));s.SetPaused(true);s.AdvanceTo(20);Assert.Equal(10000,Qty(s,FieldSupply.Carry));Assert.Empty(s.DiagnosticSnapshot().Supply!.Uses);}
    [Fact] public void ReturnAndSecondSortieDoNotMergeAcrossHandover(){var s=New();Load(s);Deploy(s);At(s,19);Assert.Equal(ResultCode.Accepted,s.SetRegionalActive(false,s.Revision).Code);Assert.Equal(ResultCode.Accepted,Load(s,Qty(s,FieldSupply.Carry),"request:return",false).Code);Assert.Equal(ResultCode.Accepted,Load(s,5000,"request:second").Code);Assert.Equal(ResultCode.Accepted,s.SetRegionalActive(true,s.Revision).Code);At(s,29);Assert.Equal(2,s.DiagnosticSnapshot().Supply!.Uses.Length);Assert.Equal(4000,Qty(s,FieldSupply.Carry));}
    [Theory][InlineData(10)][InlineData(20)][InlineData(30)][InlineData(60)]
    public void SaveRestoreKeepsStockAndContinuesExactly(int at){var s=New();Load(s);Deploy(s);At(s,at);s.SetPaused(true);var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"supply-"+Guid.NewGuid().ToString("N")),s.DiagnosticSnapshot().Definitions);store.Save(s,"case",s.DiagnosticSnapshot().WorldId,new(0,1));var host=new WorldSessionHost(New());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("case"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));At(s,80);At(host.Current,80);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));}
    [Theory][InlineData("quantity")][InlineData("owner")][InlineData("holder")][InlineData("capacity")][InlineData("consumption")]
    public void ForgedStockOrConsumptionCannotLoad(string kind){var s=New();Load(s);Deploy(s);At(s,20);var w=s.DiagnosticSnapshot();w.ResourceLots=w.ResourceLots.Select(l=>l.Id==FieldSupply.Carry?kind switch{"quantity"=>l with{Quantity=l.Quantity+1},"owner"=>l with{Owner=s.PlayerControl},"holder"=>l with{MobileHolder=RetainerStart.Lord},_=>l}:l).ToArray();if(kind=="capacity")w.Supply=w.Supply! with{Terms=w.Supply.Terms with{Capacity=999}};if(kind=="consumption")w.Supply!.Uses[0]=w.Supply.Uses[0] with{Consumed=w.Supply.Uses[0].Consumed+1};Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}
    [Fact] public void OldProfilesRejectMobileInventoryAndSupplyModules(){var w=EngagementMission.Create();w.Supply=FieldSupply.Create().Supply;Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));w=CreatedCampaign.Create();w.ResourceLots[0]=w.ResourceLots[0] with{MobileHolder=w.PlayerControl};Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}
    [Fact] public void BattleUsesActualStrengthOnEachSideOfLossTime(){var s=New();Load(s,FieldSupply.Capacity);Deploy(s);Assert.Equal(ResultCode.Accepted,s.IssueRegional(new(new("request:fight"),s.PlayerControl,s.PlayerControl,RegionalAction.Engage,new(0,0),new(10000,0)),s.Revision).Code);At(s,80);var w=s.DiagnosticSnapshot();var own=w.Region!.Units.Where(u=>u.Commander==s.PlayerControl).Select(u=>u.Id).ToHashSet();var losses=w.Region.Losses.Where(l=>own.Contains(l.Unit)).ToArray();Assert.NotEmpty(losses);long required=100*(80-9)-losses.Sum(l=>l.Soldiers*(80-l.At));Assert.Equal(required,w.Supply!.Uses.Sum(u=>u.Consumed));Assert.Equal(FieldSupply.Capacity-required,FieldSupply.Carried(w).Quantity);Assert.True(w.Supply.Uses.Length<=losses.Length+1);}
    [Fact] public void HandoverLocationCannotBeRewritten(){var s=New();Load(s);var w=s.DiagnosticSnapshot();var move=w.Supply!.Moves[0];w.Supply.Moves[0]=move with{Location=move.Location with{Site=new("site:kofu")}};Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}
    [Fact] public void OldEngagementFixtureKeepsNullMobileFieldsAndExactDefinition(){var w=ContractJson.Read<ContractWorld>(File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory,"Fixtures","engagement-511fe68-initial.json")));Assert.Null(w.Supply);Assert.All(w.ResourceLots,l=>Assert.Null(l.MobileHolder));Assert.Equal(ContractJson.CanonicalHash(EngagementMission.Create("検証配置家臣")),ContractJson.CanonicalHash(w));}

}
